// Parse the model's JSON answer and keep the original email fields
return $input.all().map((item, i) => {
  let out = {};
  try { out = JSON.parse(item.json.choices[0].message.content); } catch (e) { out = { parse_error: true }; }
  const src = $('New Mail').all()[i]?.json || {};
  return { json: { ...out, messageId: src.id, threadId: src.threadId, from: src.from?.text || src.from, subject: src.subject, snippet: (src.text || src.snippet || '').slice(0, 2000) } };
});

const c = $('Config').first().json;
const map = { urgent: c.LABEL_URGENT, lead: c.LABEL_LEAD, billing: c.LABEL_BILLING, newsletter: c.LABEL_NEWSLETTER };
// Only label mail the model classified cleanly; failed parses stay untriaged and are retried next run
return $input.all()
  .filter(i => !i.json.parse_error && i.json.category && i.json.messageId)
  .map(i => ({ json: { ...i.json, labelId: map[i.json.category] || c.LABEL_OTHER, triagedLabelId: c.LABEL_TRIAGED } }));
